public void read(final InputStream in) throws ConfigurationException
{
    try
    {
        final Yaml yaml = new Yaml();
        final Map<String, Object> map;
        {
            map = (Map) yaml.load(in);
            load(map);
        }
    }
    catch (final Exception e)
    {
        rethrowException(e);
    }
}
